create extension if not exists pgcrypto;
create type public.article_status as enum ('draft','review','scheduled','published','archived');
create type public.user_role as enum ('reader','reporter','editor','admin');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,avatar_url text,role user_role not null default 'reader',created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text unique not null,slug text unique not null);
create table public.articles(id uuid primary key default gen_random_uuid(),author_id uuid references public.profiles(id),category_id uuid references public.categories(id),category text not null default 'General',title text not null,slug text unique not null,excerpt text,body jsonb not null default '[]',cover_url text,status article_status not null default 'draft',is_breaking boolean default false,is_premium boolean default false,published_at timestamptz,scheduled_at timestamptz,views bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.shorts(id uuid primary key default gen_random_uuid(),article_id uuid references public.articles(id) on delete set null,title text not null,summary text not null,media_url text,position int default 0,is_published boolean default false,created_at timestamptz default now());
create table public.polls(id uuid primary key default gen_random_uuid(),question text not null,is_active boolean default true,closes_at timestamptz,created_at timestamptz default now());
create table public.poll_options(id uuid primary key default gen_random_uuid(),poll_id uuid references public.polls(id) on delete cascade,label text not null,position int default 0);
create table public.poll_votes(id uuid primary key default gen_random_uuid(),poll_id uuid references public.polls(id) on delete cascade,option_id uuid references public.poll_options(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,created_at timestamptz default now(),unique(poll_id,user_id));
create table public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade unique,provider text,status text not null default 'inactive',plan text,period_end timestamptz,created_at timestamptz default now());
create table public.bookmarks(user_id uuid references auth.users(id) on delete cascade,article_id uuid references public.articles(id) on delete cascade,created_at timestamptz default now(),primary key(user_id,article_id));
create table public.analytics_events(id bigint generated always as identity primary key,article_id uuid references public.articles(id) on delete set null,event text not null,session_id text,user_id uuid references auth.users(id) on delete set null,created_at timestamptz default now());
create index articles_status_published_idx on public.articles(status,published_at desc);create index analytics_article_created_idx on public.analytics_events(article_id,created_at desc);
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.articles enable row level security;alter table public.shorts enable row level security;alter table public.polls enable row level security;alter table public.poll_options enable row level security;alter table public.poll_votes enable row level security;alter table public.subscriptions enable row level security;alter table public.bookmarks enable row level security;alter table public.analytics_events enable row level security;
create policy "published articles are public" on public.articles for select to anon,authenticated using(status='published');create policy "public categories" on public.categories for select to anon,authenticated using(true);create policy "public shorts" on public.shorts for select to anon,authenticated using(is_published);create policy "public active polls" on public.polls for select to anon,authenticated using(is_active);create policy "public poll options" on public.poll_options for select to anon,authenticated using(true);
create policy "own profile" on public.profiles for select to authenticated using((select auth.uid())=id);create policy "own subscription" on public.subscriptions for select to authenticated using((select auth.uid())=user_id);create policy "own bookmarks read" on public.bookmarks for select to authenticated using((select auth.uid())=user_id);create policy "own bookmarks add" on public.bookmarks for insert to authenticated with check((select auth.uid())=user_id);create policy "own bookmarks delete" on public.bookmarks for delete to authenticated using((select auth.uid())=user_id);create policy "vote once" on public.poll_votes for insert to authenticated with check((select auth.uid())=user_id);
create policy "staff manage articles" on public.articles for all to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('reporter','editor','admin'))) with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('reporter','editor','admin')));